PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar not null default 'player', "google_id" varchar, "firstname" varchar);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "members" ("id" integer primary key autoincrement not null, "name" varchar not null, "prenom" varchar not null, "type" varchar not null, "user_id" integer, "birthdate" date, "licence" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "member_user" ("id" integer primary key autoincrement not null, "user_id" integer not null, "member_id" integer not null, "relation" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("member_id") references "members"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "member_team" ("id" integer primary key autoincrement not null, "team_id" integer not null, "member_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("team_id") references "teams"("id") on delete cascade, foreign key("member_id") references "members"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "team_user" ("id" integer primary key autoincrement not null, "team_id" integer not null, "user_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("team_id") references "teams"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "game_member" ("id" integer primary key autoincrement not null, "game_id" integer not null, "member_id" integer not null, "availability" varchar, "selected" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("game_id") references "games"("id") on delete cascade, foreign key("member_id") references "members"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "game_options" ("id" integer primary key autoincrement not null, "name" varchar not null, "created_at" datetime, "updated_at" datetime, team_id integer, display text, type text, 'order' integer);
CREATE TABLE IF NOT EXISTS "game_member_option" ("id" integer primary key autoincrement not null, "game_id" integer not null, "member_id" integer not null, "game_option_id" integer not null, "value" varchar, "created_at" datetime, "updated_at" datetime, foreign key("game_id") references "games"("id") on delete cascade, foreign key("member_id") references "members"("id") on delete cascade, foreign key("game_option_id") references "game_options"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "trainings" ("id" integer primary key autoincrement not null, "team_id" integer not null, "titre" varchar not null, "date" datetime not null, "location" varchar, "created_at" datetime, "updated_at" datetime, foreign key("team_id") references "teams"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "member_training" ("id" integer primary key autoincrement not null, "training_id" integer not null, "member_id" integer not null, "present" varchar not null default 'maybe', "comment" varchar, "created_at" datetime, "updated_at" datetime, foreign key("training_id") references "trainings"("id") on delete cascade, foreign key("member_id") references "members"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "invitations" ("id" integer primary key autoincrement not null, "email" varchar, "token" varchar not null, "user_id" integer not null, "created_by" integer not null, "expires_at" datetime, "used" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("created_by") references "users"("id"));
CREATE TABLE IF NOT EXISTS "teams" ("id" integer primary key autoincrement not null, "name" varchar not null, "owner_id" integer, "created_at" datetime, "updated_at" datetime, whatsapp varchar, msg_convocation varchar, foreign key("owner_id") references users("id") on delete no action on update no action);
CREATE TABLE IF NOT EXISTS "team_owner" ("id" integer primary key autoincrement not null, "team_id" integer not null, "user_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("team_id") references "teams"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "push_subscriptions" ("id" integer primary key autoincrement not null, "subscribable_type" varchar not null, "subscribable_id" integer not null, "endpoint" varchar not null, "public_key" varchar, "auth_token" varchar, "content_encoding" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "Places" ("id" integer primary key autoincrement not null, "name" varchar not null, "lat" float not null, "lng" float not null, "address" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "games" ("id" integer primary key autoincrement not null, "team_id" integer not null, "date" datetime not null, "location" varchar not null, "rendezvous" varchar not null, "created_at" datetime, "updated_at" datetime, "titre" varchar, "score" varchar, "commentaire" varchar, "place_id" integer, numero integer, foreign key("team_id") references teams("id") on delete cascade on update no action, foreign key("place_id") references "places"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "events" ("id" integer primary key autoincrement not null, "team_id" integer not null, "titre" varchar not null, "description" varchar, "date" datetime not null, "location" varchar, "created_at" datetime, "updated_at" datetime, foreign key("team_id") references "teams"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "event_member" ("id" integer primary key autoincrement not null, "event_id" integer not null, "member_id" integer not null, "availability" varchar, "created_at" datetime, "updated_at" datetime, foreign key("event_id") references "events"("id") on delete cascade, foreign key("member_id") references "members"("id") on delete cascade);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "invitations_token_unique" on "invitations" ("token");
CREATE UNIQUE INDEX "team_owner_team_id_user_id_unique" on "team_owner" ("team_id", "user_id");
CREATE INDEX "push_subscriptions_subscribable_morph_idx" on "push_subscriptions" ("subscribable_type", "subscribable_id");
CREATE UNIQUE INDEX "push_subscriptions_endpoint_unique" on "push_subscriptions" ("endpoint");
COMMIT;
